  set: function (obj, prop, value) {
    console.log('setting', prop, 'to', value);
    return Reflect.set(obj, prop, value); // 委托給預設行為，真的把值寫進去
  },
};
var p = new Proxy(target, handler);
p.name = 'Kyle';
console.log(target.name);

